import { useEffect, useMemo, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { createEntity, deleteEntity, listEntities, updateEntity } from '../lib/core'
import { useWorkspace } from '../lib/workspace'

const TABS=[
 ['dashboard','Dashboard'],['today','Today'],['calendar','Calendar'],['program','Programs'],
 ['library','Exercise Library'],['videos','Video Library'],['accessories','Accessories'],['templates','Templates'],
 ['workout','Start Workout'],['history','History'],['progress','Progress'],['photos','Progress Photos'],
 ['reviews','Weekly Reviews'],['assessments','Cycle Assessments'],['settings','Settings']
]
const today=()=>new Date().toISOString().slice(0,10)
const weekStart=()=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d}
const iso=d=>new Date(d).toISOString().slice(0,10)
const num=v=>v===''||v==null?null:Number(v)

function Card({title,children,actions}){return <section className="card fitness-card"><div className="section-head"><h3>{title}</h3>{actions}</div>{children}</section>}
function Metric({label,value,sub,alert}){return <div className={`metric ${alert?'alert':''}`}><div className="muted">{label}</div><strong>{value}</strong>{sub&&<div className="muted">{sub}</div>}</div>}
function Empty({text='No data yet.'}){return <div className="empty-state"><span>○</span><div>{text}</div></div>}
function Btn({children,...p}){return <button className="secondary" {...p}>{children}</button>}
function Primary({children,...p}){return <button className="primary" {...p}>{children}</button>}
function Status({children}){return <span className="status-badge info">{children}</span>}

function YouTubeEmbed({video,compact=false}){
  if(!video)return <div className="video-placeholder"><div>🎬</div><strong>No verified video assigned</strong><span className="muted">Attach a primary or backup YouTube video to publish this exercise.</span></div>
  const verified=video.verification_status==='verified'
  return <div className={`video-shell ${compact?'compact':''}`}>
    {verified?<iframe title={video.name} src={video.embed_url} loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen/>:<div className="video-placeholder"><div className="video-pill">{video.verification_status}</div><strong>{video.name}</strong><span className="muted">Video verification is pending. Use Open on YouTube while review is incomplete.</span><a className="primary" href={video.source_url} target="_blank" rel="noreferrer">Open on YouTube</a></div>}
    <div className="video-footer"><span>{video.category||'General'} · {video.difficulty||'—'}</span><span>{verified?'Verified':'Needs verification'}</span></div>
  </div>
}

function useFitnessData(workspaceId,projectId){
  const tables={
    programs:'uos_fitness_programs',cycles:'uos_fitness_cycles',phases:'uos_fitness_phases',weeks:'uos_fitness_weeks',days:'uos_fitness_workout_days',
    templates:'uos_fitness_workout_templates',blocks:'uos_fitness_template_exercise_blocks',accessoryBlocks:'uos_fitness_template_accessory_blocks',
    exercises:'uos_fitness_exercises',videos:'uos_fitness_videos',routines:'uos_fitness_accessory_routines',sessions:'uos_fitness_sessions',sets:'uos_fitness_set_logs',cardio:'uos_fitness_cardio_logs',
    progress:'uos_fitness_progress_records',photos:'uos_fitness_progress_photos',reviews:'uos_fitness_weekly_reviews',assessments:'uos_fitness_cycle_assessments',completions:'uos_fitness_accessory_completions',recovery:'uos_fitness_recovery',measurements:'uos_fitness_measurements'
  }
  const [data,setData]=useState(Object.fromEntries(Object.keys(tables).map(k=>[k,[]]))),[error,setError]=useState(''),[busy,setBusy]=useState(false)
  const load=async()=>{if(!workspaceId)return;setBusy(true);setError('');try{const values=await Promise.all(Object.values(tables).map(t=>listEntities(t,workspaceId)));const next=Object.fromEntries(Object.keys(tables).map((k,i)=>[k,values[i]||[]]));const scoped=x=>projectId?(x||[]).filter(v=>v.project_id===projectId||!v.project_id):x||[];for(const k of Object.keys(next))next[k]=scoped(next[k]);setData(next)}catch(e){setError(e.message)}finally{setBusy(false)}}
  useEffect(()=>{load()},[workspaceId,projectId])
  return {data,error,busy,load,tables}
}

export default function Fitness(){
 const {id:projectId}=useParams();const {workspace}=useWorkspace();const [tab,setTab]=useState('dashboard');const [selectedExercise,setSelectedExercise]=useState(null);const [selectedPhotoType,setSelectedPhotoType]=useState('Front')
 const {data,error,busy,load}=useFitnessData(workspace?.id,projectId)
 if(!workspace)return <div className="card">Loading Fitness OS…</div>
 const currentProgram=data.programs.find(x=>x.status==='active')||data.programs[0]
 const todayDays=data.days.filter(x=>x.scheduled_date===today())
 const weekDays=Array.from({length:7},(_,i)=>{const d=weekStart();d.setDate(d.getDate()+i);const day=iso(d);return {date:day,rows:data.days.filter(x=>x.scheduled_date===day)}})
 const doneDays=data.days.filter(x=>x.status==='completed').length
 const completion=data.days.length?Math.round(doneDays/data.days.length*100):0
 const verifiedVideos=data.videos.filter(v=>v.verification_status==='verified').length
 const missingVideos=data.exercises.filter(e=>!e.archived_at&&!e.primary_video_id&&!e.backup_video_id).length
 return <div className="fitness-os">
  <header className="page-head fitness-hero">
   <div><div className="eyebrow">PERSONAL OS · FITNESS</div><h1>Fitness OS</h1><p className="muted">One execution surface for Programs → Cycles → Phases → Weeks → Workout Days → Sessions → Sets/Cardio.</p><div className="chip-row"><span className="chip selected">{projectId?'Project scoped':'Workspace wide'}</span><span className="chip">Plan ≠ Actual</span><span className="chip">Immutable workout snapshots</span><span className={`chip ${missingVideos?'chip-warning':''}`}>{missingVideos?`${missingVideos} exercises need video`:'Video coverage ready'}</span></div></div>
   <div className="actions"><Link className="secondary" to={projectId?`/projects/${projectId}`:'/personal'}>Back</Link><Primary onClick={load}>{busy?'Refreshing…':'Refresh'}</Primary></div>
  </header>
  {error&&<div className="error">{error}</div>}
  <div className="fitness-tabs">{TABS.map(([k,l])=><button data-fitness-tab={k} key={k} className={`fitness-tab ${tab===k?'active':''}`} onClick={()=>setTab(k)}>{l}</button>)}</div>
  {tab==='dashboard'&&<Dashboard currentProgram={currentProgram} todayDays={todayDays} weekDays={weekDays} completion={completion} sessions={data.sessions} routines={data.routines} progress={data.progress} verifiedVideos={verifiedVideos} onStart={()=>setTab('workout')}/>} 
  {tab==='today'&&<TodayView days={todayDays} templates={data.templates} blocks={data.blocks} exercises={data.exercises} videos={data.videos} onStart={()=>setTab('workout')} />}
  {tab==='calendar'&&<CalendarView weekDays={weekDays} onDayClick={()=>setTab('workout')}/>} 
  {tab==='program'&&<ProgramsView workspaceId={workspace.id} projectId={projectId} data={data} load={load}/>} 
  {tab==='library'&&<LibraryView data={data} selectedExercise={selectedExercise} setSelectedExercise={setSelectedExercise}/>} 
  {tab==='videos'&&<VideosView workspaceId={workspace.id} projectId={projectId} data={data} load={load}/>} 
  {tab==='accessories'&&<AccessoriesView workspaceId={workspace.id} projectId={projectId} data={data} load={load}/>} 
  {tab==='templates'&&<TemplatesView workspaceId={workspace.id} projectId={projectId} data={data} load={load}/>} 
  {tab==='workout'&&<WorkoutView workspaceId={workspace.id} projectId={projectId} data={data} load={load}/>} 
  {tab==='history'&&<HistoryView data={data}/>} 
  {tab==='progress'&&<ProgressView workspaceId={workspace.id} projectId={projectId} data={data} load={load}/>} 
  {tab==='photos'&&<PhotosView workspaceId={workspace.id} projectId={projectId} data={data} load={load} selectedPhotoType={selectedPhotoType} setSelectedPhotoType={setSelectedPhotoType}/>} 
  {tab==='reviews'&&<ReviewsView workspaceId={workspace.id} projectId={projectId} data={data} load={load}/>} 
  {tab==='assessments'&&<AssessmentsView workspaceId={workspace.id} projectId={projectId} data={data} load={load}/>} 
  {tab==='settings'&&<FitnessSettings data={data}/>} 
 </div>
}

function Dashboard({currentProgram,todayDays,weekDays,completion,sessions,routines,progress,verifiedVideos,onStart}){
 const latest=[...progress].sort((a,b)=>String(b.measured_at).localeCompare(String(a.measured_at)))[0]
 const lastSession=[...sessions].sort((a,b)=>String(b.started_at).localeCompare(String(a.started_at)))[0]
 return <>
  <section className="fitness-kpi-grid"><Metric label="Today's workout" value={todayDays.length||0} sub={todayDays[0]?.day_name||'No scheduled workout'}/><Metric label="Current program" value={currentProgram?.name||'—'} sub={currentProgram?.goal||'Set a training goal'}/><Metric label="Completion" value={`${completion}%`} sub="Across scheduled workout days"/><Metric label="Current video coverage" value={verifiedVideos} sub="Verified YouTube videos"/></section>
  <section className="fitness-feature-grid section">
   <Card title="Today → Execute" actions={<span className="status-badge good">Execution ready</span>}><div className="today-spotlight">{todayDays.length?todayDays.slice(0,2).map(day=><div className="spotlight-row" key={day.id}><div><strong>{day.day_name||'Workout'}</strong><div className="muted">{day.scheduled_date} · {day.intensity||'moderate'} · {day.status}</div></div><button className="primary" onClick={onStart}>Start</button></div>):<Empty text="No workout scheduled for today."/>}</div></Card>
   <Card title="Current program"><div className="program-timeline"><div className="timeline-item"><span>Program</span><strong>{currentProgram?.name||'—'}</strong></div><div className="timeline-item"><span>Cycle</span><strong>Mapped by active weeks</strong></div><div className="timeline-item"><span>Phase</span><strong>Mapped by current phase</strong></div><div className="timeline-item"><span>Last session</span><strong>{lastSession?new Date(lastSession.started_at).toLocaleDateString('en-GB'):'—'}</strong></div></div></Card>
   <Card title="Recovery + progress"><div className="mini-stat"><span>Weight</span><strong>{latest?.weight??'—'}</strong></div><div className="mini-stat"><span>Sleep</span><strong>{latest?.average_sleep??'—'} h</strong></div><div className="mini-stat"><span>Accessories</span><strong>{routines.length}</strong></div></Card>
  </section>
  <section className="section"><div className="section-head"><h2>This Week</h2><Status>{weekDays.filter(x=>x.rows.some(r=>r.status==='completed')).length}/7 completed</Status></div><div className="week-strip">{weekDays.map(({date,rows})=><div className={`week-card ${rows.some(r=>r.status==='completed')?'done':''}`} key={date}><div className="muted">{new Date(date).toLocaleDateString('en-US',{weekday:'short'})}</div><strong>{new Date(date).getDate()}</strong>{rows[0]?<><span>{rows[0].day_name||'Workout'}</span><Status>{rows[0].status}</Status></>:<span className="muted">Rest / open</span>}</div>)}</div></section>
 </>
}

function TodayView({days,templates,blocks,exercises,videos,onStart}){
 if(!days.length)return <section className="section"><Empty text="No workout scheduled for today."/></section>
 return <section className="section"><div className="today-exec-grid">{days.map(day=>{const template=templates.find(t=>t.id===day.template_id);const tBlocks=blocks.filter(b=>b.template_id===template?.id).sort((a,b)=>(a.block_order||0)-(b.block_order||0));return <Card key={day.id} title={day.day_name||'Workout'} actions={<Status>{day.status}</Status>}><div className="muted">{day.scheduled_date} · {day.intensity||'Moderate'} · {template?.name||'No template'}</div><div className="exercise-preview">{tBlocks.slice(0,6).map(b=>{const ex=exercises.find(e=>e.id===b.exercise_id);return <div key={b.id} className="preview-row"><span>{b.block_order+1}. {ex?.name||'Exercise'}</span><span>{b.sets||ex?.default_sets||'—'} × {b.target_reps||ex?.default_reps||'—'}</span></div>})}</div><button className="primary full-width" onClick={onStart}>Start Workout</button>{tBlocks[0]&&<div className="muted" style={{marginTop:8}}>First movement: {exercises.find(e=>e.id===tBlocks[0].exercise_id)?.name||'—'} · {videos.find(v=>v.id===exercises.find(e=>e.id===tBlocks[0].exercise_id)?.primary_video_id)?.verification_status||'needs video'}</div>}</Card>})}</div></section>
}

function CalendarView({weekDays}){return <section className="section"><Card title="Workout Calendar" actions={<Status>Dynamic current week</Status>}><div className="calendar-workout-grid">{weekDays.map(({date,rows})=><div key={date} className="calendar-workout-day"><div className="muted">{new Date(date).toLocaleDateString('en-US',{weekday:'short'})}</div><strong>{new Date(date).toLocaleDateString('en-US',{day:'numeric',month:'short'})}</strong>{rows.length?rows.map(r=><div className="calendar-workout-item" key={r.id}><strong>{r.day_name||'Workout'}</strong><span>{r.status}</span></div>):<div className="muted calendar-rest">Rest</div>}</div>)}</div></Card></section>}

function ProgramsView({workspaceId,projectId,data,load}){
 const [program,setProgram]=useState({name:'',goal:'',status:'active',start_date:today(),end_date:''}),[cycle,setCycle]=useState({program_id:'',name:'',number:'',goal:'',start_week:'',end_week:'',status:'planned'}),[phase,setPhase]=useState({program_id:'',cycle_id:'',name:'',sort_order:'0',phase_type:'training',is_deload:false}),[week,setWeek]=useState({program_id:'',cycle_id:'',phase_id:'',week_number:'',label:'',start_date:'',end_date:'',status:'planned'}),[day,setDay]=useState({week_id:'',template_id:'',scheduled_date:today(),day_name:'',day_ordinal:'',status:'not_started',intensity:'moderate',difficulty:'',energy_level:'',notes:''})
 const save=async(table,value,reset)=>{try{await createEntity(table,{workspace_id:workspaceId,project_id:projectId||null,...value});reset();load()}catch(e){alert(e.message)}}
 return <section className="section"><div className="section-intro"><div><h2>Program Builder</h2><p className="muted">Build the hierarchy once, then schedule repeatable workout days.</p></div><Status>{data.programs.length} programs</Status></div>
  <div className="builder-grid">
   <Card title="01 · Program"><form className="form-stack" onSubmit={e=>{e.preventDefault();save('uos_fitness_programs',program,()=>setProgram({name:'',goal:'',status:'active',start_date:today(),end_date:''}))}}><input placeholder="Program name" value={program.name} onChange={e=>setProgram({...program,name:e.target.value})} required/><textarea placeholder="Goal" value={program.goal} onChange={e=>setProgram({...program,goal:e.target.value})}/><div className="form-grid"><input type="date" value={program.start_date} onChange={e=>setProgram({...program,start_date:e.target.value})}/><input type="date" value={program.end_date} onChange={e=>setProgram({...program,end_date:e.target.value})}/></div><Primary>Create Program</Primary></form></Card>
   <Card title="02 · Cycle"><form className="form-stack" onSubmit={e=>{e.preventDefault();save('uos_fitness_cycles',{...cycle,program_id:cycle.program_id||data.programs[0]?.id,number:num(cycle.number),start_week:num(cycle.start_week),end_week:num(cycle.end_week)},()=>setCycle({program_id:'',name:'',number:'',goal:'',start_week:'',end_week:'',status:'planned'}))}}><select value={cycle.program_id} onChange={e=>setCycle({...cycle,program_id:e.target.value})}><option value="">Program</option>{data.programs.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><input placeholder="Cycle name" value={cycle.name} onChange={e=>setCycle({...cycle,name:e.target.value})} required/><div className="form-grid"><input type="number" placeholder="Number" value={cycle.number} onChange={e=>setCycle({...cycle,number:e.target.value})}/><input placeholder="Goal" value={cycle.goal} onChange={e=>setCycle({...cycle,goal:e.target.value})}/></div><div className="form-grid"><input type="number" placeholder="Start week" value={cycle.start_week} onChange={e=>setCycle({...cycle,start_week:e.target.value})}/><input type="number" placeholder="End week" value={cycle.end_week} onChange={e=>setCycle({...cycle,end_week:e.target.value})}/></div><Primary>Create Cycle</Primary></form></Card>
   <Card title="03 · Phase"><form className="form-stack" onSubmit={e=>{e.preventDefault();save('uos_fitness_phases',{...phase,program_id:phase.program_id||data.programs[0]?.id,cycle_id:phase.cycle_id||null,sort_order:num(phase.sort_order)||0},()=>setPhase({program_id:'',cycle_id:'',name:'',sort_order:'0',phase_type:'training',is_deload:false}))}}><select value={phase.program_id} onChange={e=>setPhase({...phase,program_id:e.target.value})}><option value="">Program</option>{data.programs.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><select value={phase.cycle_id} onChange={e=>setPhase({...phase,cycle_id:e.target.value})}><option value="">Cycle</option>{data.cycles.filter(c=>!phase.program_id||c.program_id===phase.program_id).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><input placeholder="Phase name" value={phase.name} onChange={e=>setPhase({...phase,name:e.target.value})} required/><div className="form-grid"><select value={phase.phase_type} onChange={e=>setPhase({...phase,phase_type:e.target.value})}><option>training</option><option>deload</option><option>test</option><option>maintenance</option></select><input type="number" placeholder="Order" value={phase.sort_order} onChange={e=>setPhase({...phase,sort_order:e.target.value})}/></div><label className="check-row"><input type="checkbox" checked={phase.is_deload} onChange={e=>setPhase({...phase,is_deload:e.target.checked})}/> Deload phase</label><Primary>Create Phase</Primary></form></Card>
   <Card title="04 · Week"><form className="form-stack" onSubmit={e=>{e.preventDefault();save('uos_fitness_weeks',{...week,program_id:week.program_id||data.programs[0]?.id,cycle_id:week.cycle_id||null,phase_id:week.phase_id||null,week_number:num(week.week_number)},()=>setWeek({program_id:'',cycle_id:'',phase_id:'',week_number:'',label:'',start_date:'',end_date:'',status:'planned'}))}}><select value={week.program_id} onChange={e=>setWeek({...week,program_id:e.target.value})}><option value="">Program</option>{data.programs.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><select value={week.cycle_id} onChange={e=>setWeek({...week,cycle_id:e.target.value})}><option value="">Cycle</option>{data.cycles.filter(c=>!week.program_id||c.program_id===week.program_id).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select value={week.phase_id} onChange={e=>setWeek({...week,phase_id:e.target.value})}><option value="">Phase</option>{data.phases.filter(p=>!week.program_id||p.program_id===week.program_id).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><div className="form-grid"><input type="number" placeholder="Week #" value={week.week_number} onChange={e=>setWeek({...week,week_number:e.target.value})}/><input placeholder="Label" value={week.label} onChange={e=>setWeek({...week,label:e.target.value})}/></div><div className="form-grid"><input type="date" value={week.start_date} onChange={e=>setWeek({...week,start_date:e.target.value})}/><input type="date" value={week.end_date} onChange={e=>setWeek({...week,end_date:e.target.value})}/></div><Primary>Create Week</Primary></form></Card>
   <Card title="05 · Workout Day"><form className="form-stack" onSubmit={e=>{e.preventDefault();save('uos_fitness_workout_days',{...day,week_id:day.week_id||null,template_id:day.template_id||null,day_ordinal:num(day.day_ordinal),energy_level:num(day.energy_level)},()=>setDay({week_id:'',template_id:'',scheduled_date:today(),day_name:'',day_ordinal:'',status:'not_started',intensity:'moderate',difficulty:'',energy_level:'',notes:''}))}}><select value={day.week_id} onChange={e=>setDay({...day,week_id:e.target.value})}><option value="">Week</option>{data.weeks.map(w=><option key={w.id} value={w.id}>Week {w.week_number} · {w.label||w.start_date}</option>)}</select><select value={day.template_id} onChange={e=>setDay({...day,template_id:e.target.value})}><option value="">Template</option>{data.templates.map(t=><option key={t.id} value={t.id}>{t.name} v{t.program_version}</option>)}</select><input type="date" value={day.scheduled_date} onChange={e=>setDay({...day,scheduled_date:e.target.value})}/><div className="form-grid"><input placeholder="Day name" value={day.day_name} onChange={e=>setDay({...day,day_name:e.target.value})}/><select value={day.intensity} onChange={e=>setDay({...day,intensity:e.target.value})}><option>easy</option><option>moderate</option><option>hard</option></select></div><Primary>Schedule Day</Primary></form></Card>
  </div>
  <div className="section"><div className="grid grid-3">{data.programs.slice(0,6).map(p=><Card key={p.id} title={p.name}><div className="muted">{p.goal||'No goal defined'}</div><div className="chip-row"><Status>{p.status}</Status><span className="chip">{data.cycles.filter(c=>c.program_id===p.id).length} cycles</span><span className="chip">{data.weeks.filter(w=>w.program_id===p.id).length} weeks</span></div></Card>)}</div></div>
 </section>
}

function LibraryView({data,selectedExercise,setSelectedExercise}){const [q,setQ]=useState('');const filtered=data.exercises.filter(x=>`${x.name} ${x.category||''} ${x.primary_muscle||''}`.toLowerCase().includes(q.toLowerCase()));const ex=selectedExercise||filtered[0];const video=data.videos.find(v=>v.id===ex?.primary_video_id)||data.videos.find(v=>v.id===ex?.backup_video_id);return <section className="section"><div className="library-layout"><div className="card library-list"><div className="section-head"><h3>Exercise Library</h3><span className="muted">{filtered.length} results</span></div><input className="search-input" placeholder="Search exercise / muscle / category" value={q} onChange={e=>setQ(e.target.value)}/>{filtered.slice(0,60).map(item=><button className={`library-row ${ex?.id===item.id?'selected':''}`} key={item.id} onClick={()=>setSelectedExercise(item)}><span><strong>{item.name}</strong><small>{item.primary_muscle||item.category||'—'}</small></span><Status>{item.difficulty||'—'}</Status></button>)}</div><div className="library-detail">{ex?<Card title={ex.name} actions={<div className="chip-row"><span className="chip">{ex.primary_muscle||'General'}</span><span className="chip">{ex.category||'Strength'}</span><span className="chip">{ex.difficulty||'—'}</span></div>}><YouTubeEmbed video={video}/><div className="detail-grid"><div><h4>How to perform</h4><p className="muted">{ex.instructions||'Add execution instructions.'}</p></div><div><h4>Sets / Reps / Rest</h4><p className="muted">{ex.default_sets||'—'} sets · {ex.default_reps||'—'} reps · {ex.rest_seconds||'—'} sec</p></div><div><h4>Progression</h4><p className="muted">{ex.progression||'Not defined'}</p></div><div><h4>Regression</h4><p className="muted">{ex.regression||'Not defined'}</p></div><div><h4>Safety</h4><p className="muted">{ex.safety_notes||'Not defined'}</p></div><div><h4>Backup</h4><p className="muted">{data.videos.find(v=>v.id===ex.backup_video_id)?.name||'—'}</p></div></div></Card>:<Empty text="Select an exercise to inspect its full training UX."/>}</div></div></section>}

function VideosView({workspaceId,projectId,data,load}){const blank={name:'',source_url:'',video_id:'',embed_url:'',verification_status:'needs_verification',category:'Strength',difficulty:'Beginner',channel:'',favorite:false,notes:''};const [value,setValue]=useState(blank),[q,setQ]=useState('');function parseUrl(raw){try{const u=new URL(raw);let id=u.searchParams.get('v');if(!id&&u.hostname.includes('youtu.be'))id=u.pathname.slice(1);if(id)setValue(v=>({...v,source_url:raw,video_id:id,embed_url:`https://www.youtube.com/embed/${id}`}));else setValue(v=>({...v,source_url:raw}))}catch{setValue(v=>({...v,source_url:raw}))}}
 const filtered=data.videos.filter(v=>`${v.name} ${v.category||''} ${v.channel||''}`.toLowerCase().includes(q.toLowerCase()));
 async function save(e){e.preventDefault();try{await createEntity('uos_fitness_videos',{workspace_id:workspaceId,project_id:projectId||null,...value});setValue(blank);load()}catch(err){alert(err.message)}}
 return <section className="section"><div className="grid grid-2"><Card title="Add / verify YouTube video"><form className="form-stack" onSubmit={save}><input placeholder="Video name" value={value.name} onChange={e=>setValue({...value,name:e.target.value})} required/><input placeholder="https://www.youtube.com/watch?v=..." value={value.source_url} onChange={e=>parseUrl(e.target.value)} required/><div className="video-parse-grid"><input placeholder="videoId" value={value.video_id} readOnly/><input placeholder="embedUrl" value={value.embed_url} readOnly/></div><div className="form-grid"><select value={value.verification_status} onChange={e=>setValue({...value,verification_status:e.target.value})}><option value="needs_verification">Needs Verification</option><option value="verified">Verified</option><option value="broken">Broken</option><option value="replaced">Replaced</option></select><input placeholder="Category" value={value.category} onChange={e=>setValue({...value,category:e.target.value})}/><input placeholder="Difficulty" value={value.difficulty} onChange={e=>setValue({...value,difficulty:e.target.value})}/></div><Primary>Add Video</Primary></form></Card><Card title="Coverage"><div className="fitness-kpi-grid compact"><Metric label="Total videos" value={data.videos.length}/><Metric label="Verified" value={data.videos.filter(v=>v.verification_status==='verified').length}/><Metric label="Broken" value={data.videos.filter(v=>v.verification_status==='broken').length}/><Metric label="Exercises missing video" value={data.exercises.filter(e=>!e.primary_video_id&&!e.backup_video_id).length}/></div></Card></div><div className="section"><div className="section-head"><h2>Video Library</h2><input className="search-input small" placeholder="Search video" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="video-grid">{filtered.map(v=><Card key={v.id} title={v.name} actions={<Status>{v.verification_status}</Status>}><YouTubeEmbed video={v} compact/><div className="muted">{v.channel||'Channel not set'} · {v.category||'General'} · {v.difficulty||'—'}</div></Card>)}</div></div></section>}

function AccessoriesView({workspaceId,projectId,data,load}){const blank={name:'',type:'Mobility',duration_minutes:'',frequency:'daily',notes:'',primary_video_id:''};const [value,setValue]=useState(blank);async function save(e){e.preventDefault();try{await createEntity('uos_fitness_accessory_routines',{workspace_id:workspaceId,project_id:projectId||null,...value,duration_minutes:num(value.duration_minutes),primary_video_id:value.primary_video_id||null});setValue(blank);load()}catch(err){alert(err.message)}}async function complete(r){try{const existing=data.completions.find(x=>x.routine_id===r.id&&x.date===today());if(existing)await updateEntity('uos_fitness_accessory_completions',existing.id,{completed:!existing.completed});else await createEntity('uos_fitness_accessory_completions',{workspace_id:workspaceId,project_id:projectId||null,routine_id:r.id,date:today(),completed:true});load()}catch(err){alert(err.message)}}return <section className="section"><div className="grid grid-2"><Card title="Create accessory routine"><form className="form-stack" onSubmit={save}><input placeholder="Routine name" value={value.name} onChange={e=>setValue({...value,name:e.target.value})} required/><div className="form-grid"><select value={value.type} onChange={e=>setValue({...value,type:e.target.value})}><option>Breathing</option><option>Face Yoga</option><option>Jawline</option><option>Kegel</option><option>Mobility</option><option>Stretching</option></select><input type="number" placeholder="Duration (min)" value={value.duration_minutes} onChange={e=>setValue({...value,duration_minutes:e.target.value})}/></div><select value={value.primary_video_id} onChange={e=>setValue({...value,primary_video_id:e.target.value})}><option value="">Primary video</option>{data.videos.map(v=><option key={v.id} value={v.id}>{v.name}</option>)}</select><textarea placeholder="Notes" value={value.notes} onChange={e=>setValue({...value,notes:e.target.value})}/><Primary>Create Routine</Primary></form></Card><Card title="Today accessories"><div className="routine-stack">{data.routines.map(r=>{const log=data.completions.find(x=>x.routine_id===r.id&&x.date===today());return <div className="routine-row" key={r.id}><div><strong>{r.name}</strong><div className="muted">{r.type} · {r.duration_minutes||'—'} min</div></div><button className={log?.completed?'primary':'secondary'} onClick={()=>complete(r)}>{log?.completed?'Completed':'Complete'}</button></div>})}</div></Card></div></section>}

function TemplatesView({workspaceId,projectId,data,load}){const blank={template_key:'',name:'',type:'Strength + MMA',muscle_group:'',base_duration:'',program_version:'1',cycle_id:'',phase_id:'',version_notes:''};const [value,setValue]=useState(blank),[selected,setSelected]=useState(null),[block,setBlock]=useState({exercise_id:'',block_order:'0',sets:'',target_reps:'',target_duration:'',rest_seconds:'',notes:''});async function saveTemplate(e){e.preventDefault();try{await createEntity('uos_fitness_workout_templates',{workspace_id:workspaceId,project_id:projectId||null,...value,base_duration:num(value.base_duration),program_version:num(value.program_version)||1,cycle_id:value.cycle_id||null,phase_id:value.phase_id||null});setValue(blank);load()}catch(err){alert(err.message)}}async function saveBlock(e){e.preventDefault();if(!selected)return;try{await createEntity('uos_fitness_template_exercise_blocks',{workspace_id:workspaceId,template_id:selected.id,...block,block_order:num(block.block_order)||0,sets:num(block.sets),target_reps:num(block.target_reps),target_duration:num(block.target_duration),rest_seconds:num(block.rest_seconds)});setBlock({exercise_id:'',block_order:'0',sets:'',target_reps:'',target_duration:'',rest_seconds:'',notes:''});load()}catch(err){alert(err.message)}}const selectedBlocks=data.blocks.filter(b=>b.template_id===selected?.id).sort((a,b)=>(a.block_order||0)-(b.block_order||0));return <section className="section"><div className="grid grid-2"><Card title="Create template"><form className="form-stack" onSubmit={saveTemplate}><input placeholder="Template key" value={value.template_key} onChange={e=>setValue({...value,template_key:e.target.value})} required/><input placeholder="Template name" value={value.name} onChange={e=>setValue({...value,name:e.target.value})} required/><div className="form-grid"><select value={value.type} onChange={e=>setValue({...value,type:e.target.value})}><option>Strength + MMA</option><option>Strength + Cardio</option><option>Recovery</option><option>Rest</option></select><input placeholder="Muscle group" value={value.muscle_group} onChange={e=>setValue({...value,muscle_group:e.target.value})}/><input type="number" placeholder="Duration" value={value.base_duration} onChange={e=>setValue({...value,base_duration:e.target.value})}/></div><div className="form-grid"><input type="number" placeholder="Program version" value={value.program_version} onChange={e=>setValue({...value,program_version:e.target.value})}/><select value={value.cycle_id} onChange={e=>setValue({...value,cycle_id:e.target.value})}><option value="">Cycle</option>{data.cycles.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select value={value.phase_id} onChange={e=>setValue({...value,phase_id:e.target.value})}><option value="">Phase</option>{data.phases.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></div><textarea placeholder="Version notes" value={value.version_notes} onChange={e=>setValue({...value,version_notes:e.target.value})}/><Primary>Create Versioned Template</Primary></form></Card><Card title="Template builder"><div className="template-picker">{data.templates.map(t=><button className={`template-item ${selected?.id===t.id?'selected':''}`} key={t.id} onClick={()=>setSelected(t)}><strong>{t.name}</strong><span>v{t.program_version}</span></button>)}</div>{selected?<><form className="form-stack" onSubmit={saveBlock} style={{marginTop:12}}><select value={block.exercise_id} onChange={e=>setBlock({...block,exercise_id:e.target.value})}><option value="">Exercise</option>{data.exercises.map(ex=><option key={ex.id} value={ex.id}>{ex.name}</option>)}</select><div className="form-grid"><input type="number" placeholder="Order" value={block.block_order} onChange={e=>setBlock({...block,block_order:e.target.value})}/><input type="number" placeholder="Sets" value={block.sets} onChange={e=>setBlock({...block,sets:e.target.value})}/><input type="number" placeholder="Reps" value={block.target_reps} onChange={e=>setBlock({...block,target_reps:e.target.value})}/></div><div className="form-grid"><input type="number" placeholder="Duration" value={block.target_duration} onChange={e=>setBlock({...block,target_duration:e.target.value})}/><input type="number" placeholder="Rest sec" value={block.rest_seconds} onChange={e=>setBlock({...block,rest_seconds:e.target.value})}/></div><Primary>Add exercise block</Primary></form><div className="section-list">{selectedBlocks.map(b=><div className="list-row between" key={b.id}><span>{b.block_order+1}. {data.exercises.find(e=>e.id===b.exercise_id)?.name||'Exercise'} · {b.sets||'—'} × {b.target_reps||'—'}</span><Btn onClick={()=>deleteEntity('uos_fitness_template_exercise_blocks',b.id).then(load)}>Remove</Btn></div>)}</div></>:<Empty text="Select a template version to compose its exact workout plan."/>}</Card></div></section>}

function WorkoutView({workspaceId,projectId,data,load}){const [selectedDay,setSelectedDay]=useState(data.days.find(d=>d.scheduled_date===today())||data.days[0]||null),[session,setSession]=useState(null),[draft,setDraft]=useState({}),[timer,setTimer]=useState({running:false,seconds:0,total:0}),[rpe,setRpe]=useState(''),[energy,setEnergy]=useState(''),[cardio,setCardio]=useState({type:'LISS',duration:'',distance:'',pace:'',speed:'',heart_rate:'',rpe:'',notes:''})
 useEffect(()=>{if(!selectedDay&&data.days.length)setSelectedDay(data.days.find(d=>d.scheduled_date===today())||data.days[0])},[data.days.length])
 useEffect(()=>{const raw=localStorage.getItem('uos_fitness_active_draft');if(raw){try{const x=JSON.parse(raw);if(x?.workspaceId===workspaceId)setDraft(x.draft||{})}catch{}}},[workspaceId])
 useEffect(()=>{localStorage.setItem('uos_fitness_active_draft',JSON.stringify({workspaceId,draft}))},[workspaceId,draft])
 useEffect(()=>{if(!timer.running)return;const id=setInterval(()=>setTimer(t=>t.seconds<=1?{...t,running:false,seconds:0}:{...t,seconds:t.seconds-1}),1000);return()=>clearInterval(id)},[timer.running])
 const template=data.templates.find(t=>t.id===selectedDay?.template_id);const blocks=data.blocks.filter(b=>b.template_id===template?.id).sort((a,b)=>(a.block_order||0)-(b.block_order||0));const start=async()=>{if(!selectedDay)return alert('Choose a workout day');if(session)return;const snapshot={template,blocks};try{const created=await createEntity('uos_fitness_sessions',{workspace_id:workspaceId,workout_id:null,workout_day_id:selectedDay.id,program_version:template?.program_version||1,status:'in_progress',started_at:new Date().toISOString(),plan_snapshot:snapshot});await updateEntity('uos_fitness_workout_days',selectedDay.id,{status:'in_progress'});setSession(created);load()}catch(err){alert(err.message)}}
 const completeSet=async(b,index)=>{if(!session)return alert('Start the workout first');const row=draft[b.id]||{};if(row.completed)return;try{const key=`${session.id}:${b.id}:${index+1}`;await createEntity('uos_fitness_set_logs',{workspace_id:workspaceId,session_id:session.id,exercise_id:b.exercise_id,set_number:index+1,reps:num(row.reps??b.target_reps),weight_load:num(row.weight),rpe:num(row.rpe),rest_seconds:num(b.rest_seconds),completed:true,notes:row.notes||'',idempotency_key:key});setDraft(d=>({...d,[b.id]:{...row,completedSets:[...(row.completedSets||[]),index+1]}}));setTimer({running:true,seconds:b.rest_seconds||60,total:b.rest_seconds||60})}catch(err){alert(err.message)}}
 const finish=async()=>{if(!session)return;const total=blocks.reduce((s,b)=>s+(b.sets||1),0);const done=Object.values(draft).reduce((sum,row)=>sum+(row.completedSets||[]).length,0);try{await updateEntity('uos_fitness_sessions',session.id,{status:'completed',ended_at:new Date().toISOString(),rpe:num(rpe),energy:num(energy),completion_percent:total?Math.round(done/total*100):100,notes:'Completed from Fitness execution'});await updateEntity('uos_fitness_workout_days',selectedDay.id,{status:'completed'});setSession(null);setDraft({});localStorage.removeItem('uos_fitness_active_draft');load()}catch(err){alert(err.message)}}
 const addCardio=async e=>{e.preventDefault();if(!session)return;try{await createEntity('uos_fitness_cardio_logs',{workspace_id:workspaceId,session_id:session.id,...cardio,duration:num(cardio.duration),distance:num(cardio.distance),pace:num(cardio.pace),speed:num(cardio.speed),heart_rate:num(cardio.heart_rate),rpe:num(cardio.rpe)});setCardio({type:'LISS',duration:'',distance:'',pace:'',speed:'',heart_rate:'',rpe:'',notes:''});load()}catch(err){alert(err.message)}}
 return <section className="section"><div className="workout-header"><div><div className="eyebrow">LIVE EXECUTION</div><h2>{selectedDay?.day_name||'Select a workout'}</h2><div className="muted">{selectedDay?.scheduled_date||'—'} · {template?.name||'No template'} · {template?`Version ${template.program_version}`:'—'}</div></div><div className="actions"><select value={selectedDay?.id||''} onChange={e=>setSelectedDay(data.days.find(d=>d.id===e.target.value)||null)}><option value="">Choose workout day</option>{data.days.slice().sort((a,b)=>String(a.scheduled_date).localeCompare(String(b.scheduled_date))).map(d=><option key={d.id} value={d.id}>{d.scheduled_date} · {d.day_name||'Workout'}</option>)}</select>{session?<Primary onClick={finish}>Finish Workout</Primary>:<Primary onClick={start}>Start Workout</Primary>}</div></div>{session?<div className="workout-live-grid"><div>{blocks.length?blocks.map(b=>{const ex=data.exercises.find(e=>e.id===b.exercise_id);const video=data.videos.find(v=>v.id===ex?.primary_video_id)||data.videos.find(v=>v.id===ex?.backup_video_id);const row=draft[b.id]||{};return <Card key={b.id} title={`${b.block_order+1}. ${ex?.name||'Exercise'}`} actions={<Status>{(row.completedSets||[]).length}/{b.sets||1} sets</Status>}><YouTubeEmbed video={video} compact/><div className="set-grid">{Array.from({length:b.sets||1},(_,i)=>{const complete=(row.completedSets||[]).includes(i+1);return <div className={`set-row ${complete?'complete':''}`} key={i}><div className="set-num">{i+1}</div><input aria-label="Reps" type="number" placeholder={b.target_reps||'Reps'} value={row.reps??''} onChange={e=>setDraft(d=>({...d,[b.id]:{...row,reps:e.target.value}}))}/><input aria-label="Load" type="number" placeholder="Load" value={row.weight??''} onChange={e=>setDraft(d=>({...d,[b.id]:{...row,weight:e.target.value}}))}/><input aria-label="RPE" type="number" min="1" max="10" placeholder="RPE" value={row.rpe??''} onChange={e=>setDraft(d=>({...d,[b.id]:{...row,rpe:e.target.value}}))}/><button className={complete?'primary':'secondary'} disabled={complete} onClick={()=>completeSet(b,i)}>{complete?'✓ Done':'Complete set'}</button></div>})}</div></Card>}) : <Empty text="This template has no exercise blocks yet."/>}</div><aside className="workout-side"><Card title="Rest timer"><div className="timer-face">{String(Math.floor(timer.seconds/60)).padStart(2,'0')}:{String(timer.seconds%60).padStart(2,'0')}</div><div className="timer-controls"><Btn onClick={()=>setTimer(t=>({...t,running:!t.running}))}>{timer.running?'Pause':'Resume'}</Btn><Btn onClick={()=>setTimer(t=>({...t,seconds:0,running:false}))}>Skip</Btn><Btn onClick={()=>setTimer(t=>({...t,seconds:t.seconds+15,total:(t.total||0)+15}))}>+15s</Btn></div></Card><Card title="Session readiness"><div className="form-grid"><input type="number" min="1" max="10" placeholder="Energy" value={energy} onChange={e=>setEnergy(e.target.value)}/><input type="number" min="1" max="10" placeholder="RPE" value={rpe} onChange={e=>setRpe(e.target.value)}/></div><div className="muted" style={{marginTop:8}}>Your draft is saved locally so leaving this screen will not erase the active workout.</div></Card><Card title="Cardio"><form className="form-stack" onSubmit={addCardio}><select value={cardio.type} onChange={e=>setCardio({...cardio,type:e.target.value})}><option>LISS</option><option>HIIT</option><option>Running</option><option>Walking</option><option>Shadow Boxing</option><option>Other</option></select><div className="form-grid"><input type="number" placeholder="Duration" value={cardio.duration} onChange={e=>setCardio({...cardio,duration:e.target.value})}/><input type="number" placeholder="Distance" value={cardio.distance} onChange={e=>setCardio({...cardio,distance:e.target.value})}/><input type="number" placeholder="RPE" value={cardio.rpe} onChange={e=>setCardio({...cardio,rpe:e.target.value})}/></div><Primary>Add cardio</Primary></form></Card></aside></div>:<Card title="Start a workout"><div className="start-workout-cta"><div><strong>{selectedDay?`Ready for ${selectedDay.day_name||'today’s workout'}`:'Choose a scheduled workout day'}</strong><p className="muted">The exact plan version will be snapshotted on session start. Every completed set is persisted immediately.</p></div><Primary onClick={start} disabled={!selectedDay}>Start Workout</Primary></div></Card>}</section>}

function HistoryView({data}){return <section className="section"><Card title="Workout History" actions={<Status>{data.sessions.length} sessions</Status>}><div className="history-list">{[...data.sessions].sort((a,b)=>String(b.started_at).localeCompare(String(a.started_at))).slice(0,30).map(s=>{const sets=data.sets.filter(x=>x.session_id===s.id);const cardio=data.cardio.filter(x=>x.session_id===s.id);return <div className="history-item" key={s.id}><div><strong>{new Date(s.started_at).toLocaleString('en-GB')}</strong><div className="muted">{s.status} · Version {s.program_version||1} · {sets.length} sets · {cardio.length} cardio logs</div></div><div className="chip-row"><span className="chip">{s.completion_percent??0}% complete</span><span className="chip">RPE {s.rpe??'—'}</span><span className="chip">Energy {s.energy??'—'}</span></div></div>})}{!data.sessions.length&&<Empty text="Completed workouts will appear here."/>}</div></Card></section>}

function ProgressView({workspaceId,projectId,data,load}){const [measurement,setMeasurement]=useState({measured_at:today(),weight_kg:'',body_fat_pct:'',resting_hr:'',notes:''}),[record,setRecord]=useState({measured_at:today(),weight:'',chest:'',waist:'',thigh:'',arm:'',energy:'',stress:'',average_sleep:'',max_push_ups:'',running_distance:'',running_time:'',plank_time:'',notes:''});const save=async(table,v,after)=>{try{await createEntity(table,{workspace_id:workspaceId,project_id:projectId||null,...v});after();load()}catch(e){alert(e.message)}};const sorted=[...data.progress].sort((a,b)=>String(a.measured_at).localeCompare(String(b.measured_at)));return <section className="section"><div className="grid grid-2"><Card title="Body measurement"><form className="form-stack" onSubmit={e=>{e.preventDefault();save('uos_fitness_measurements',measurement,()=>setMeasurement({measured_at:today(),weight_kg:'',body_fat_pct:'',resting_hr:'',notes:''}))}}><div className="form-grid"><input type="date" value={measurement.measured_at} onChange={e=>setMeasurement({...measurement,measured_at:e.target.value})}/><input type="number" step="0.1" placeholder="Weight kg" value={measurement.weight_kg} onChange={e=>setMeasurement({...measurement,weight_kg:e.target.value})}/><input type="number" step="0.1" placeholder="Body fat %" value={measurement.body_fat_pct} onChange={e=>setMeasurement({...measurement,body_fat_pct:e.target.value})}/></div><input type="number" placeholder="Resting HR" value={measurement.resting_hr} onChange={e=>setMeasurement({...measurement,resting_hr:e.target.value})}/><textarea placeholder="Notes" value={measurement.notes} onChange={e=>setMeasurement({...measurement,notes:e.target.value})}/><Primary>Save measurement</Primary></form></Card><Card title="Weekly progress record"><form className="form-stack" onSubmit={e=>{e.preventDefault();save('uos_fitness_progress_records',{...record,weight:num(record.weight),chest:num(record.chest),waist:num(record.waist),thigh:num(record.thigh),arm:num(record.arm),energy:num(record.energy),stress:num(record.stress),average_sleep:num(record.average_sleep),max_push_ups:num(record.max_push_ups),running_distance:num(record.running_distance),running_time:num(record.running_time),plank_time:num(record.plank_time)},()=>setRecord({...record,weight:'',chest:'',waist:'',thigh:'',arm:'',energy:'',stress:'',average_sleep:'',max_push_ups:'',running_distance:'',running_time:'',plank_time:''}))}}><div className="form-grid"><input type="date" value={record.measured_at} onChange={e=>setRecord({...record,measured_at:e.target.value})}/><input type="number" placeholder="Weight" value={record.weight} onChange={e=>setRecord({...record,weight:e.target.value})}/><input type="number" placeholder="Max pushups" value={record.max_push_ups} onChange={e=>setRecord({...record,max_push_ups:e.target.value})}/></div><div className="form-grid"><input placeholder="Chest" value={record.chest} onChange={e=>setRecord({...record,chest:e.target.value})}/><input placeholder="Waist" value={record.waist} onChange={e=>setRecord({...record,waist:e.target.value})}/><input placeholder="Thigh" value={record.thigh} onChange={e=>setRecord({...record,thigh:e.target.value})}/></div><div className="form-grid"><input placeholder="Energy /10" value={record.energy} onChange={e=>setRecord({...record,energy:e.target.value})}/><input placeholder="Stress /10" value={record.stress} onChange={e=>setRecord({...record,stress:e.target.value})}/><input placeholder="Sleep h" value={record.average_sleep} onChange={e=>setRecord({...record,average_sleep:e.target.value})}/></div><textarea placeholder="What changed this week?" value={record.notes} onChange={e=>setRecord({...record,notes:e.target.value})}/><Primary>Save progress</Primary></form></Card></div><div className="section"><Card title="Progress history"><div className="progress-history">{sorted.slice(-12).map((r,i)=>{const prev=sorted[i-1];const delta=prev?.weight!=null&&r.weight!=null?Number(r.weight)-Number(prev.weight):null;return <div className="history-item" key={r.id}><div><strong>{r.measured_at}</strong><div className="muted">Weight {r.weight??'—'} · Waist {r.waist??'—'} · Push-ups {r.max_push_ups??'—'}</div></div><span className="chip">Δ weight {delta==null?'—':delta.toFixed(1)}</span></div>})}{!sorted.length&&<Empty text="Add your first progress record."/>}</div></Card></div></section>}

function PhotosView({workspaceId,projectId,data,load,selectedPhotoType,setSelectedPhotoType}){const [value,setValue]=useState({date:today(),type:'Front',file_url:'',week_id:'',phase_id:'',cycle_id:''});async function save(e){e.preventDefault();try{await createEntity('uos_fitness_progress_photos',{workspace_id:workspaceId,project_id:projectId||null,...value});setValue({...value,file_url:''});load()}catch(err){alert(err.message)}}const typePhotos=data.photos.filter(p=>p.type===selectedPhotoType).sort((a,b)=>String(a.date).localeCompare(String(b.date)));const start=typePhotos[0],end=typePhotos[typePhotos.length-1];return <section className="section"><div className="grid grid-2"><Card title="Add progress photo"><form className="form-stack" onSubmit={save}><div className="form-grid"><input type="date" value={value.date} onChange={e=>setValue({...value,date:e.target.value})}/><select value={value.type} onChange={e=>setValue({...value,type:e.target.value})}><option>Front</option><option>Side</option><option>Back</option></select></div><input placeholder="Secure file URL / storage path" value={value.file_url} onChange={e=>setValue({...value,file_url:e.target.value})} required/><select value={value.week_id} onChange={e=>setValue({...value,week_id:e.target.value})}><option value="">Week</option>{data.weeks.map(w=><option key={w.id} value={w.id}>Week {w.week_number}</option>)}</select><Primary>Save photo reference</Primary></form></Card><Card title="Start vs End compare"><div className="photo-compare-tabs">{['Front','Side','Back'].map(t=><button className={`fitness-tab ${selectedPhotoType===t?'active':''}`} onClick={()=>setSelectedPhotoType(t)} key={t}>{t}</button>)}</div><div className="photo-compare"><Photo src={start?.file_url} label={start?`Start · ${start.date}`:'Start'}/><Photo src={end?.file_url} label={end&&end!==start?`End · ${end.date}`:'End'}/></div></Card></div><div className="section"><Card title={`${selectedPhotoType} timeline`}><div className="photo-timeline">{typePhotos.map(p=><div key={p.id} className="photo-thumb"><img src={p.file_url} alt={p.type}/><span>{p.date}</span></div>)}{!typePhotos.length&&<Empty text="No photos for this angle yet."/>}</div></Card></div></section>}
function Photo({src,label}){return <div className="photo-frame"><div className="muted">{label}</div>{src?<img src={src} alt={label}/>:<div className="photo-empty">No image</div>}</div>}

function ReviewsView({workspaceId,projectId,data,load}){const blank={week_id:'',title:'',skipped_workouts:'0',strength_score:'',cardio_score:'',mobility_score:'',recovery_score:'',mma_score:'',energy_score:'',improved:'',difficult:'',next_week_change:''};const [v,setV]=useState(blank);async function save(e){e.preventDefault();try{await createEntity('uos_fitness_weekly_reviews',{workspace_id:workspaceId,project_id:projectId||null,...v,skipped_workouts:num(v.skipped_workouts),strength_score:num(v.strength_score),cardio_score:num(v.cardio_score),mobility_score:num(v.mobility_score),recovery_score:num(v.recovery_score),mma_score:num(v.mma_score),energy_score:num(v.energy_score)});setV(blank);load()}catch(err){alert(err.message)}}return <section className="section"><div className="grid grid-2"><Card title="Weekly Review"><form className="form-stack" onSubmit={save}><select value={v.week_id} onChange={e=>setV({...v,week_id:e.target.value})}><option value="">Week</option>{data.weeks.map(w=><option key={w.id} value={w.id}>Week {w.week_number} · {w.label||w.start_date}</option>)}</select><input placeholder="Review title" value={v.title} onChange={e=>setV({...v,title:e.target.value})} required/><div className="score-grid">{[['strength_score','Strength'],['cardio_score','Cardio'],['mobility_score','Mobility'],['recovery_score','Recovery'],['mma_score','MMA'],['energy_score','Energy']].map(([k,l])=><label key={k}><span>{l} /10</span><input type="number" min="0" max="10" value={v[k]} onChange={e=>setV({...v,[k]:e.target.value})}/></label>)}</div><textarea placeholder="What improved?" value={v.improved} onChange={e=>setV({...v,improved:e.target.value})}/><textarea placeholder="What was difficult?" value={v.difficult} onChange={e=>setV({...v,difficult:e.target.value})}/><textarea placeholder="What changes next week?" value={v.next_week_change} onChange={e=>setV({...v,next_week_change:e.target.value})}/><Primary>Save Weekly Review</Primary></form></Card><Card title="Recent reviews">{[...data.reviews].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,10).map(r=><div className="history-item" key={r.id}><div><strong>{r.title}</strong><div className="muted">Week {data.weeks.find(w=>w.id===r.week_id)?.week_number||'—'}</div></div><span className="chip">Energy {r.energy_score??'—'}</span></div>)}{!data.reviews.length&&<Empty text="Your weekly review history will appear here."/>}</Card></div></section>}

function AssessmentsView({workspaceId,projectId,data,load}){const blank={cycle_id:'',completion_percent:'',max_push_ups:'',weight:'',running_distance:'',running_time:'',strength_notes:'',cardio_notes:'',mma_footwork_score:'',energy:'',difficulty:'',flexibility:'',recovery:'',what_worked:'',what_needs_change:'',next_cycle_plan:''};const [v,setV]=useState(blank);async function save(e){e.preventDefault();try{await createEntity('uos_fitness_cycle_assessments',{workspace_id:workspaceId,project_id:projectId||null,...v,completion_percent:num(v.completion_percent),max_push_ups:num(v.max_push_ups),weight:num(v.weight),running_distance:num(v.running_distance),running_time:num(v.running_time),mma_footwork_score:num(v.mma_footwork_score),energy:num(v.energy),difficulty:num(v.difficulty),flexibility:num(v.flexibility),recovery:num(v.recovery)});setV(blank);load()}catch(err){alert(err.message)}}return <section className="section"><div className="grid grid-2"><Card title="Cycle Assessment"><form className="form-stack" onSubmit={save}><select value={v.cycle_id} onChange={e=>setV({...v,cycle_id:e.target.value})}><option value="">Cycle</option>{data.cycles.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><div className="form-grid"><input placeholder="Completion %" value={v.completion_percent} onChange={e=>setV({...v,completion_percent:e.target.value})}/><input placeholder="Max push-ups" value={v.max_push_ups} onChange={e=>setV({...v,max_push_ups:e.target.value})}/><input placeholder="Weight" value={v.weight} onChange={e=>setV({...v,weight:e.target.value})}/></div><div className="form-grid"><input placeholder="Running distance" value={v.running_distance} onChange={e=>setV({...v,running_distance:e.target.value})}/><input placeholder="Running time" value={v.running_time} onChange={e=>setV({...v,running_time:e.target.value})}/><input placeholder="MMA/Footwork score" value={v.mma_footwork_score} onChange={e=>setV({...v,mma_footwork_score:e.target.value})}/></div><div className="score-grid">{[['energy','Energy'],['difficulty','Difficulty'],['flexibility','Flexibility'],['recovery','Recovery']].map(([k,l])=><label key={k}><span>{l}</span><input value={v[k]} onChange={e=>setV({...v,[k]:e.target.value})}/></label>)}</div><textarea placeholder="What worked" value={v.what_worked} onChange={e=>setV({...v,what_worked:e.target.value})}/><textarea placeholder="What needs change" value={v.what_needs_change} onChange={e=>setV({...v,what_needs_change:e.target.value})}/><textarea placeholder="Next-cycle plan" value={v.next_cycle_plan} onChange={e=>setV({...v,next_cycle_plan:e.target.value})}/><Primary>Save Assessment</Primary></form></Card><Card title="Assessment history">{[...data.assessments].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).map(a=><div className="history-item" key={a.id}><div><strong>{data.cycles.find(c=>c.id===a.cycle_id)?.name||'Cycle'}</strong><div className="muted">Completion {a.completion_percent??'—'}% · Push-ups {a.max_push_ups??'—'}</div></div><Status>Archived snapshot</Status></div>)}{!data.assessments.length&&<Empty text="End-of-cycle assessments will appear here."/>}</Card></div></section>}

function FitnessSettings({data}){const exportData=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`fitness-export-${today()}.json`;a.click();URL.revokeObjectURL(url)};return <section className="section"><div className="grid grid-3"><Card title="Plan vs Actual"><strong>Schedules are plans.</strong><p className="muted">Templates are reusable plans. Sessions preserve the exact program version used. SetLog/CardioLog contain actual execution.</p></Card><Card title="YouTube publishing gate"><strong>{data.exercises.filter(e=>!e.archived_at&&!e.primary_video_id&&!e.backup_video_id).length} exercises need video</strong><p className="muted">Active exercises without a primary/backup video are flagged for review before publication.</p></Card><Card title="Local recovery"><strong>Active session drafts persist</strong><p className="muted">The execution screen stores the current draft locally so leaving the screen does not erase entered sets.</p></Card></div><div className="section"><Card title="Data export"><p className="muted">Export the current Fitness view as JSON for audit, backup, or QA review.</p><Primary onClick={exportData}>Export Fitness JSON</Primary></Card></div></section>}
